/* --- ASTRAL GLASSMORPHISM --- */
.app * {
	border-color: rgba(100, 150, 255, 0.15) !important;
}

/* Ethereal Typography */
.markdown-prose h1, .markdown-prose h2, .markdown-prose h3, .markdown-prose h4 {
	color: #aaddff !important;
	text-shadow: 0 0 15px rgba(136, 187, 255, 0.2);
}
.markdown-prose code {
	color: #cdd3f5 !important;
	background-color: rgba(136, 187, 255, 0.1) !important;
	border: 1px solid rgba(136, 187, 255, 0.2);
	border-radius: 6px;
}

/* Frosted Glass Inputs */
input, textarea, #chat-input-container, .bg-gray-850 {
	background-color: rgba(10, 11, 20, 0.5) !important;
	backdrop-filter: blur(12px) !important;
	-webkit-backdrop-filter: blur(12px) !important;
	border: 1px solid rgba(136, 187, 255, 0.2) !important;
	border-radius: 12px !important;
	box-shadow: inset 0 0 10px rgba(0, 0, 0, 0.5);
	transition: all 0.3s ease;
}
input:focus, textarea:focus, #chat-input-container:focus-within {
	border-color: #88bbff !important;
	background-color: rgba(16, 18, 35, 0.7) !important;
	box-shadow: 0 0 20px rgba(136, 187, 255, 0.2), inset 0 0 10px rgba(0, 0, 0, 0.5) !important;
}

/* Starship Buttons */
button.bg-blue-500, button.bg-blue-600, .bg-black {
	background: linear-gradient(135deg, #4488ff, #8855ff) !important;
	border: none !important;
	color: #ffffff !important;
	font-weight: 600 !important;
	border-radius: 20px !important;
	box-shadow: 0 4px 15px rgba(68, 136, 255, 0.3);
	transition: transform 0.2s cubic-bezier(0.4, 0, 0.2, 1), box-shadow 0.2s;
}
button.bg-blue-500:hover, button.bg-blue-600:hover, .bg-black:hover {
	transform: translateY(-3px) scale(1.02);
	box-shadow: 0 8px 25px rgba(136, 85, 255, 0.5) !important;
}

/* Liquid Scrollbar */
::-webkit-scrollbar-thumb {
	background: linear-gradient(to bottom, #4488ff, #8855ff) !important;
	border-radius: 10px;
}
::-webkit-scrollbar-track {
	background: rgba(5, 5, 10, 0.5) !important;
}

/* ─────────────────────────────────────────────────────────────
 * Font menu for Open WebUI
 *
 * Paste at the TOP LEVEL of ONE Style Overrides slot, Auto-Scope OFF.
 * Not inside any rule: @font-face is invalid nested in a selector.
 * Raw mode emits it verbatim, so it reaches every mode from
 * whichever slot holds it. One slot only.
 *
 * Then set  Settings -> Interface -> Font Family  to any name below,
 * spelled exactly, with no comma and no fallbacks. To change font
 * later, retype the name. No CSS editing.
 *
 * Nothing downloads until a font is actually selected: a declared
 * @font-face stays 'unloaded' until text needs it. Declaring twelve
 * costs one HTTP request, for the one in use.
 *
 * These are web fonts, so they work even where the browser hides
 * installed system fonts from pages (Firefox ETP strict with
 * fingerprinting protection does exactly that).
 *
 *   IBM Plex Sans               humanist, sturdy stems, drawn for screens; holds up behind blur
 *   Inter Tight                 a tighter Inter; closest to Open WebUI's stock look
 *   Source Sans 3               classic UI humanist, very legible at small sizes
 *   Public Sans                 neutral and sturdy, little personality by design
 *   Figtree                     soft geometric, rounded and warm
 *   Manrope                     semi-geometric, tall x-height, modern
 *   Work Sans                   open apertures, friendly, easy at UI sizes
 *   Nunito Sans                 rounded terminals, the softest option here
 *   Lato                        humanist and calm; static, so only 400 and 700
 *   Atkinson Hyperlegible Next  drawn for low vision; most robust over a busy background
 *   Space Grotesk               characterful and techy, quirkier letterforms
 *   Outfit                      clean geometric, geometric 'a' and 'g'
 *
 * To add another Google font, take its name and run:
 *
 *   curl -s -H 'User-Agent: Mozilla/5.0 (X11; Linux x86_64) \
 *     AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126 Safari/537.36' \
 *     'https://fonts.googleapis.com/css2?family=Font+Name:wght@400..700&display=swap'
 *
 * then paste the latin and latin-ext @font-face blocks it prints.
 * A plain browser visit returns TTF, not woff2; the User-Agent matters.
 * ───────────────────────────────────────────────────────────── */

